    const dt = Math.min(0.1, (now - last) / 1000); last = now; time += dt;
    resize();
    const target = opts.progress ? clamp(opts.progress(), 0, 1) : (() => { const d = opts.autoplay ?? 40, u = (time / d) % 2; return u < 1 ? u : 2 - u; })();
    p = first ? target : p + (target - p) * (1 - Math.exp(-dt * (opts.damping ?? 3.2)));
    ptr.sx += (ptr.x - ptr.sx) * (1 - Math.exp(-dt * 2.5)); ptr.sy += (ptr.y - ptr.sy) * (1 - Math.exp(-dt * 2.5));
    U.uTime.value = time;
