    U.uPx.value = H / (2 * Math.tan(camera.fov * Math.PI / 360));
    cur.update?.(time, p, dt);
    if (scene.fog) { U.uFogCol.value.copy(scene.fog.color); U.uFogDen.value = scene.fog.density ?? 0; } else U.uFogDen.value = 0;
    if (scene.environment && scene.fog) U.uAmbF.value.copy(scene.fog.color).multiplyScalar(scene.environmentIntensity * 0.6); else U.uAmbF.value.set(0, 0, 0);
    camera.updateMatrixWorld();
